namespace {
int checks=0;
const char* guide_ids[]={"guide-x","guide-y"};
const char* sources[]={"10 + 0.5","20 + 0.5"};
void check(bool ok,const char* why){if(!ok)throw std::runtime_error(why);++checks;}
void events(){QApplication::processEvents();QApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QTest::qWait(15);}
template<class T>T* control(Window& w,const QString& name){for(auto* c:w.findChildren<T*>(name))if(c->isVisible())return c;throw std::runtime_error(("Missing control: "+name).toStdString());}
QString name(int field,const char* suffix){
 if(QString(suffix)=="-expression")return "guide-position-expression-"+QString(guide_ids[field]);
 if(QString(suffix)=="-apply-expression")return "guide-position-apply-expression-"+QString(guide_ids[field]);
 return "guide-position-"+QString(guide_ids[field]);
}
void reveal(QWidget* c){for(auto* p=c->parentWidget();p;p=p->parentWidget())if(auto* s=qobject_cast<QScrollArea*>(p))s->ensureWidgetVisible(c);events();check(c->isVisible(),"Exact production control visible");}
void valid(const Document& d){validate(d);check(decode(encode(d))==d,"Independent full Document native-valid BEFORE Window");}
Document fixture(int mode){
 auto d=empty_document("guide-prefix-"+std::to_string(mode),"composition","board");auto& comp=d.compositions.front();auto& b=comp.artboards.front();b.width=1200;b.height=900;
 b.layout=ArtboardLayout{Margin{10.123456789012345,20.234567890123456,30.345678901234567,40.456789012345678},Grid{"grid",{15.123456789012345,20.234567890123456,1000.1234567890123,800.23456789012345},3,2,7.345678901234567,8.456789012345678}};
 comp.guides={{"guide-x","Vertical","x",10.123456789012345},{"guide-y","Horizontal","y",20.234567890123456},{"peer","Untouched peer","x",30.345678901234567}};comp.guides[2].position_driver=Ref{"guide-x","","guide.position"};Guide py{"peer-y","Untouched y peer","y",40.456789012345678};py.position_driver=Ref{"guide-y","","guide.position"};comp.guides.push_back(py);
 Object o;o.id="sentinel";o.kind=Kind::path;Contour c;c.id="contour";Point p;p.id="point";p.x.literal=51.25;p.y.literal=-21.75;c.points={p};o.contours={c};d.objects.emplace(o.id,o);comp.roots={o.id};valid(d);return d;
}
Document wanted(const Document& initial,int field){auto d=initial;d.compositions.front().guides[field].position_expression=Expression{sources[field],1};valid(d);return d;}
std::vector<Command> command(int field,const char* body=nullptr){return {SetGuidePositionExpression{{guide_ids[field],"","guide.position"},{body?body:sources[field],1},false}};}
Session gesture_commit(const Document& d,int field){Session expected(d);expected.begin_gesture(0);expected.update_gesture(command(field));expected.commit_gesture();return expected;}
void same(const Session& a,const Session& b){if(!(a.document()==b.document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation()))std::cerr<<"Snapshot doc="<<(a.document()==b.document())<<" history="<<(a.history()==b.history())<<" rev="<<a.revision()<<"/"<<b.revision()<<" active="<<a.gesture_active()<<"/"<<b.gesture_active()<<" gen="<<a.gesture_generation()<<"/"<<b.gesture_generation()<<"\n";check(a.document()==b.document()&&encode(a.document())==encode(b.document())&&a.preview_document()==b.preview_document()&&a.history()==b.history()&&a.revision()==b.revision()&&a.gesture_active()==b.gesture_active()&&a.gesture_generation()==b.gesture_generation(),"Full canonical Session equals independent pre-Window expectation");}
void write(const QString& path,const Document& d){QFile f(path);const auto bytes=encode(d);check(f.open(QIODevice::WriteOnly|QIODevice::NewOnly)&&f.write(bytes.data(),bytes.size())==static_cast<qint64>(bytes.size()),"Independent native oracle retained once");}
QByteArray read(const QString& path){QFile f(path);check(f.open(QIODevice::ReadOnly),"Owned native bytes readable");return f.readAll();}
QString prefix(const QString& root,int mode){return root+"/mode-"+QString::number(mode);}
void open(Window& w,const Document& d){w.host.session=Session(d);w.host.edited();w.canvas->set_active_artboard("composition","board",false);w.resize(1400,1000);w.show();w.activateWindow();events();auto* dock=w.findChild<QDockWidget*>("properties");check(dock,"Properties exists");dock->show();dock->raise();events();auto* edit=control<QPushButton>(w,"artboard-edit");reveal(edit);edit->click();events();}
void enter_prefix(Window& w,int field,const QString& text){auto* input=control<QLineEdit>(w,"guide-position-"+QString(guide_ids[field]));reveal(input);input->setFocus();QTest::keyClick(input,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(input,text);events();QTest::keyClick(input,Qt::Key_Return);events();}
void enter_numeric(Window& w,int field,const QString& text,bool commit){auto* input=control<QLineEdit>(w,"guide-position-"+QString(guide_ids[field]));reveal(input);input->setFocus();QTest::keyClick(input,Qt::Key_A,Qt::ControlModifier);QTest::keyClicks(input,text);events();if(commit){QTest::keyClick(input,Qt::Key_Return);events();}}
void cancel(Window& w,int field){auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_Escape);events();}
void apply(Window& w,int field){auto* editor=control<QPlainTextEdit>(w,name(field,"-expression"));reveal(editor);editor->setFocus();QTest::keyClick(editor,Qt::Key_Return,Qt::ControlModifier);events();}
void reset(Window& w,const Document& d,const QString& key){w.host.session=Session(d);w.host.session_id+=key;w.host.edited();events();}

Document relative_goal(const Document& initial,int f,double delta){auto d=initial;d.compositions.front().guides[f].position=initial.compositions.front().guides[f].position+delta;valid(d);return d;}
std::vector<Command> update(const Document& d,int f){return {UpdateGuide{"composition",d.compositions.front().guides[f]}};}
Session preview(const Document& initial,const Document& goal,int f){Session s(initial);s.begin_gesture(0);s.update_gesture(update(goal,f));return s;}
void cold_relative(const QString& root,int mode){const int f=mode%2;const double delta=mode<2?2.25:-2.25;const auto d=relative_goal(fixture(mode),f,delta);Session expected(d);const auto path=prefix(root,mode);QSettings settings(root+"/cold-settings.ini",QSettings::IniFormat);Window w(path+"-cold",std::make_unique<FolderLibrary>(settings),&settings);w.host.open(path+"-cold-input.nect");same(w.host.session,expected);w.host.save(path+"-resaved.nect");w.host.flush();same(w.host.session,expected);check(read(path+"-cold-input.nect")==read(path+"-expected.nect")&&read(path+"-resaved.nect")==read(path+"-expected.nect"),"Separate cold exact relative/native refs");QTest::qWait(120);}
void flow_relative(const QString& root,int mode){
 const int f=mode%2;const double sign=mode<2?1:-1;const QString first=sign>0?"+=0.5":"-=0.5",second=sign>0?"+=2.25":"-=2.25";
 const auto initial=fixture(mode),first_goal=relative_goal(initial,f,sign*0.5),goal=relative_goal(initial,f,sign*2.25);Session before(initial),direct(initial);direct.apply(update(goal,f),0);// Actual native Ctrl+A reselection retires only the owned preview; next
 // gesture still uses the captured initial Document, without author/History.
 auto first_preview=preview(initial,first_goal,f),retarget=first_preview;retarget.cancel_gesture();retarget.begin_gesture(0);retarget.update_gesture(update(goal,f));auto committed=retarget;committed.commit_gesture();check(direct.document()==goal&&committed.document()==goal&&direct.history()==committed.history(),"Full independent relative goal/typed command/lifecycle BEFORE Window");check(evaluate_guide_position(goal,"composition",f?"peer-y":"peer")==goal.compositions.front().guides[f].position,"Independent same-axis stable peer reference follows target BEFORE Window");
 auto absolute_doc=initial;absolute_doc.compositions.front().guides[f].position=-3.25;valid(absolute_doc);auto absolute=preview(initial,absolute_doc,f);absolute.commit_gesture();auto plus_literal_doc=initial;plus_literal_doc.compositions.front().guides[f].position=10;valid(plus_literal_doc);auto plus_literal=preview(initial,plus_literal_doc,f);plus_literal.commit_gesture();
 auto external=initial.compositions.front().artboards.front();external.name="External caller";Session foreign(initial);foreign.begin_gesture(0);foreign.update_gesture({UpdateArtboard{"composition",external}});auto foreign_goal=initial;foreign_goal.compositions.front().artboards.front().name=external.name;valid(foreign_goal);check(foreign.preview_document()==foreign_goal,"Independent foreign relative preview BEFORE Window");Session generation=first_preview;generation.cancel_gesture();generation.begin_gesture(0);generation.update_gesture({UpdateArtboard{"composition",external}});
 auto replacement=initial;replacement.id+="-replacement";valid(replacement);Session replaced(replacement),newer(initial);newer.apply({UpdateArtboard{"composition",external}},0);auto driven_doc=initial;driven_doc.compositions.front().guides[f].position_expression=Expression{"42",1};valid(driven_doc);Session driven(driven_doc);
 auto cancelled=first_preview;cancelled.cancel_gesture();
 // Keyboard typing visits finite prefixes before the final invalid string.
 // Keep the last independently valid prefix preview; author/History stay initial.
 std::array<Session,6> invalid_expected{before,before,before,before,before,before};
 invalid_expected[3]=preview(initial,relative_goal(initial,f,1000),f);
 invalid_expected[4]=preview(initial,relative_goal(initial,f,-1000),f);
 invalid_expected[5]=preview(initial,relative_goal(initial,f,1),f);
 auto boundary=initial;boundary.compositions.front().guides[f].position=1e9;valid(boundary);Session boundary_before(boundary);auto boundary_preview=preview(boundary,boundary,f);auto outside=boundary.compositions.front().guides[f];outside.position+=0.5;Session boundary_api(boundary);QString range_code;try{boundary_api.apply({UpdateGuide{"composition",outside}},0);}catch(const Error& e){range_code=QString::fromStdString(e.code);}check(!range_code.isEmpty(),"Independent finite out-of-range core refusal BEFORE Window");same(boundary_api,boundary_before);auto boundary_cancelled=boundary_preview;boundary_cancelled.cancel_gesture();// Refused Return retires the owned transient preview; no authored state.
 for(int i=3;i<6;++i)invalid_expected[i].cancel_gesture();
 const auto path=prefix(root,mode);write(path+"-initial.nect",initial);write(path+"-expected.nect",goal);QSettings settings(root+"/settings.ini",QSettings::IniFormat);Window w(path+"-recovery",std::make_unique<FolderLibrary>(settings),&settings);open(w,initial);same(w.host.session,before);enter_numeric(w,f,first,false);std::cout<<"RELATIVE mode="<<mode<<" input="<<first.toStdString()<<" status="<<w.statusBar()->currentMessage().toStdString()<<"\n";same(w.host.session,first_preview);check(!w.statusBar()->currentMessage().contains("INVALID"),"Valid current relative preview clears incomplete-prefix error");check(w.host.session.document()==initial&&w.host.session.history()==before.history(),"Relative preview has no authored/History mutation");enter_numeric(w,f,second,false);same(w.host.session,retarget);check(!w.statusBar()->currentMessage().contains("INVALID"),"Valid relative retype clears its transient error");check(w.host.session.preview_document().compositions.front().guides[f].position==initial.compositions.front().guides[f].position+sign*2.25,"Retyping uses captured initial double, never prior preview");
 auto* input=control<QLineEdit>(w,"guide-position-"+QString(guide_ids[f]));check(input->parentWidget()->grab().save(path+"-relative-preview.png"),"Actual relative row render retained");input->setFocus();QTest::keyClick(input,Qt::Key_Return);events();same(w.host.session,committed);check(w.host.session.document()==goal,"One relative commit preserves full IDs/peer refs/source/literals/layout/sentinel");
 w.host.save(path+"-saved.nect");w.host.flush();events();same(w.host.session,committed);check(QFile::copy(path+"-saved.nect",path+"-cold-input.nect"),"Retain relative bytes before Undo");QProcess child;child.start(QCoreApplication::applicationFilePath(),{"--cold",root,QString::number(mode)});check(child.waitForStarted(5000),"Owned relative cold starts");if(!child.waitForFinished(15000)){child.kill();child.waitForFinished();throw std::runtime_error("Owned cold deadline");}std::cout<<child.readAllStandardOutput().toStdString();std::cerr<<child.readAllStandardError().toStdString();check(child.exitStatus()==QProcess::NormalExit&&child.exitCode()==0,"Owned relative cold passes");w.host.session.undo(w.host.session.revision());committed.undo(committed.revision());w.host.edited();events();same(w.host.session,committed);check(w.host.session.document()==initial,"One relative Undo restores full initial source/refs/literals/IDs");w.host.session.redo(w.host.session.revision());committed.redo(committed.revision());w.host.edited();events();same(w.host.session,committed);
 reset(w,initial,"-cancel");enter_numeric(w,f,first,false);same(w.host.session,first_preview);auto* cancel_input=control<QLineEdit>(w,"guide-position-"+QString(guide_ids[f]));cancel_input->setFocus();QTest::keyClick(cancel_input,Qt::Key_Escape);events();same(w.host.session,cancelled);check(control<QLineEdit>(w,"guide-position-"+QString(guide_ids[f]))->text()==QString::number(initial.compositions.front().guides[f].position,'g',15),"Escape restores initial numeric display/full source refs");
 reset(w,boundary,"-range");enter_numeric(w,f,"+=0.5",false);same(w.host.session,boundary_preview);check(w.statusBar()->currentMessage().contains(range_code),"Relative finite range failure uses existing core refusal and retains last valid zero-prefix preview");auto* range_input=control<QLineEdit>(w,"guide-position-"+QString(guide_ids[f]));range_input->setFocus();QTest::keyClick(range_input,Qt::Key_Return);events();same(w.host.session,boundary_cancelled);check(w.statusBar()->currentMessage().contains("INVALID_LAYOUT"),"Invalid range draft cannot commit its last valid transient prefix");
 reset(w,initial,"-absolute");enter_numeric(w,f,"-3.25",true);same(w.host.session,absolute);reset(w,initial,"-plus-literal");enter_numeric(w,f,"+10",true);same(w.host.session,plus_literal);
 int invalid_index=0;for(const auto* invalid:{"+=","-=","+=oops","+=1e309","-=1e309","+=1 / 0"}){reset(w,initial,"-invalid-"+QString(invalid));enter_numeric(w,f,invalid,true);same(w.host.session,invalid_expected[invalid_index++]);check(w.host.session.document()==initial&&w.host.session.history()==before.history(),"Invalid relative never authors last valid transient prefix");check(w.statusBar()->currentMessage().contains("INVALID_VALUE"),"Incomplete/nonfinite/non-number relative refused without zero/author/History");check(control<QLineEdit>(w,"guide-position-"+QString(guide_ids[f]))->text()==invalid,"Invalid relative remains exact editable input");}
 reset(w,initial,"-session");w.host.session_id+="-other";enter_numeric(w,f,first,true);same(w.host.session,before);check(w.statusBar()->currentMessage().contains("SESSION_CONFLICT"),"Old relative input Session refusal");
 reset(w,initial,"-document");w.host.session=Session(replacement);enter_numeric(w,f,first,true);same(w.host.session,replaced);check(w.statusBar()->currentMessage().contains("SESSION_CONFLICT"),"Same Session/revision replacement Document relative refusal");
 reset(w,initial,"-revision");w.host.session.apply({UpdateArtboard{"composition",external}},0);enter_numeric(w,f,first,true);same(w.host.session,newer);check(w.statusBar()->currentMessage().contains("REVISION_CONFLICT"),"Old revision relative refusal");
 reset(w,initial,"-foreign");w.host.session.begin_gesture(0);w.host.session.update_gesture({UpdateArtboard{"composition",external}});w.host.edited();events();enter_numeric(w,f,first,true);same(w.host.session,foreign);check(w.statusBar()->currentMessage().contains("GESTURE_ACTIVE"),"Relative preserves foreign caller");
 reset(w,initial,"-generation");enter_numeric(w,f,first,false);w.host.session.cancel_gesture();w.host.session.begin_gesture(0);w.host.session.update_gesture({UpdateArtboard{"composition",external}});enter_numeric(w,f,second,true);same(w.host.session,generation);check(w.statusBar()->currentMessage().contains("GESTURE_ACTIVE")||w.statusBar()->currentMessage().contains("REVISION_CONFLICT"),"Relative preserves replacement caller generation");
 reset(w,driven_doc,"-driven");enter_numeric(w,f,first,true);same(w.host.session,driven);check(control<QLineEdit>(w,"guide-position-"+QString(guide_ids[f]))->isReadOnly()&&control<QPlainTextEdit>(w,name(f,"-expression"))->toPlainText()=="42","Driven numeric relative remains readonly/source preserved");
}
}
int main(int argc,char** argv){qputenv("QT_QPA_PLATFORM","windows");QApplication app(argc,argv);try{std::cout<<"Native platform="<<QGuiApplication::platformName().toStdString()<<" PID="<<QCoreApplication::applicationPid()<<"\n";if(argc==4&&std::string(argv[1])=="--cold")cold_relative(QString::fromLocal8Bit(argv[2]),std::stoi(argv[3]));else{QTemporaryDir temporary;check(temporary.isValid(),"Owned scratch valid");const auto requested=qEnvironmentVariable("NECT_GUIDE_RELATIVE_ROOT"),root=requested.isEmpty()?temporary.path():requested;int failures=0;for(int mode=0;mode<4;++mode){try{flow_relative(root,mode);std::cout<<"CASE PASS mode="<<mode<<"\n";}catch(const std::exception& e){++failures;std::cerr<<"CASE FAIL mode="<<mode<<" reason="<<e.what()<<" checks="<<checks<<"\n";}}if(failures)throw std::runtime_error("Independent relative cases failed: "+std::to_string(failures));}std::cout<<"PASS Guide relative input "<<checks<<" checks\n";return 0;}catch(const std::exception& e){std::cerr<<"FAIL Guide relative input "<<e.what()<<" after "<<checks<<" checks\n";return 1;}}
